using System.Data;
using System.Data.Common;
using System.Globalization;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage;
using Qms.Application.InternalAudits;
using Qms.Application.Security;
using Qms.Contracts.Common;
using Qms.Contracts.InternalAudits;
using Qms.Domain.AuditTrail;
using Qms.Domain.Capas;
using Qms.Domain.InternalAudits;
using Qms.Domain.QualityRecords;
